SENTINELS = {'data/objects_config.json': '        "_declared": "The drawer\'s rows, by slug, in order outward from the Sun. Every row except the Sun can be ticked, one at a time, and ticking a row also opens it. A GROUP row (group, label) gathers the body rows that name it in their in field, listed after it: it is always listed, folded shut, and a tap folds it open to show them or shut again; it ticks nothing, and once one of its bodies is ticked its Reset unticks them all. There is no See more and nothing ticks many bodies at once: Tony\'s rulings of 2026-10-24 (L-477), the visitor builds the view one body at a time; order a lists its bodies by their served semi-major axis, nearest first, and without it they keep the order here (the comets, by first apparition; the spacecraft, by launch). Each group of small bodies is JPL\'s own class for its bodies (its Small-Body Database); the Spacecraft group follows Earth\'s row, as the comets follow the Sun (Tony\'s ruling of 2026-10-24, L-443). Tony\'s ruling of 2026-10-22 (L-443): groups fold open in the drawer, and a room is for a body with more than its symbol. A row may carry the words a visitor sees for it: label, the name shown in the drawer and text box when it is not the served name; about, a sentence shown in the text box and the panel; source_note, what the Horizons id in the source line is. Tony\'s rulings, 2026-09-29 and 2026-09-30 (L-363).",', 'tools/mirror_objects.py': '                  window and step (PATH_FIELDS, EVENT_FIELDS). The cache builder', 'tools/test_mirror_objects.py': '    by8 = {o["slug"]: o for o in json.loads(mo.apply(cfg4, edits))["objects"]}', 'tools/gallery_cache_builder.py': "                                 'band': 'spacecraft-sanity(0<r<%g, t increasing)' % SPACECRAFT_SANITY_AU,", 'tools/test_gallery_cache_builder_offline.py': "                           {'d': {'jd': 1.0, 'x': 1500.0, 'y': 0, 'z': 0}}, None, None, 2.0, None)", 'gallery/assembler/render_spacecraft.py': '                            legendgroup: str) -> Tuple[List[Tuple[str, Dict[str, Any]]], List[str]]:', 'gallery/assembler/cache_reader.py': 'fetched, {slug: parsed positions/<slug>.json}, read by position_file(); it', 'gallery/assembler/assemble.py': 'from . import render_orbits, render_objects, render_spacecraft, presentation', 'gallery/assembler/presentation.py': "    # L-443 build B, 2026-10-25: the twelve spacecraft, in the orrery's own", 'gallery/assembler/render_orbits.py': '    # mean conic should be dashed instead is a Mode 5 choice, at artifact 4.)', 'gallery/solar_system_figures.js': '// is drawn from its served positions, and its marker is worked out between', 'interactive.html': '                            else { warnings.push(label + ": no orbit line -- " + orb.why); }', 'documentation/smoke_solar_system_figures.js': '    failures.push(slug + ": serves no path plan (run tools/mirror_objects.py after the orrery\'s export is pulled)");', 'tools/headless/run_room_driver.py': '        "POS_JSON": json.dumps(position_files(json.loads(cov), json.loads(cfg))),', 'tools/headless/walk_solar_system_drawer.js': '    const crafts = E("ssDrawer.rows.filter(r => r.group === \'spacecraft\' && !SolarSystemDrawer.isGroup(r)).map(r => r.key).join(\',\')");', 'daily_run.py': '            print("    1. In GitHub Desktop, open the orrery and push it (or, if")', 'gallery_maintenance_run.py': 'positions files, which the Solar System room fetches before it draws.)'}
POST_CALLS = []


def fail(msg):
    print(msg)
    print("NOTHING was written. Undo is not needed.")
    sys.exit(1)


def main():
    same_new = set()
    for rel, content in NEW_FILES:
        full = os.path.join(HERE, *rel.split("/"))
        if os.path.exists(full):
            have = open(full, "rb").read().replace(b"\r\n", b"\n")
            if have == content.encode("utf-8"):
                same_new.add(rel)
                continue
            fail("ERROR: %s already exists and differs from what this patch "
                 "writes. Most likely a copy of the same document saved from "
                 "a download or an attachment: delete it and run this patch "
                 "again." % rel)
    staged = []
    for rel, edits in EDITS:
        path = os.path.join(HERE, *rel.split("/"))
        if not os.path.isfile(path):
            fail("ERROR: not found: %s -- is this file in the right folder?"
                 % path)
        raw = open(path, "rb").read()
        crlf = b"\r\n" in raw
        text = raw.replace(b"\r\n", b"\n").decode("utf-8")
        if SENTINELS.get(rel) and SENTINELS[rel] in text:
            fail("ERROR: %s already carries this patch's change; this "
                 "patch has run." % rel)
        for k, (old, new) in enumerate(edits):
            n = text.count(old)
            if n != 1:
                if new and text.count(new) == 1 and old not in text:
                    fail("ERROR: %s already carries edit %d of %d; this "
                         "patch has run." % (rel, k + 1, len(edits)))
                fail("ANCHOR FAIL in %s, edit %d of %d: expected 1 match, "
                     "found %d" % (rel, k + 1, len(edits), n))
            text = text.replace(old, new)
        staged.append((rel, path, text, crlf, len(edits)))
    for rel, path, text, crlf, n in staged:
        open(path, "wb").write(text.encode("utf-8"))
        print("ok  %s (%d edits)" % (rel, n))
        if crlf:
            print("note: %s was CRLF in the working copy; written LF" % rel)
        bad = sum(1 for c in text if ord(c) > 127)
        if bad:
            print("note: %s holds %d non-ASCII character(s) this patch did "
                  "not add" % (rel, bad))
    for rel, content in NEW_FILES:
        full = os.path.join(HERE, *rel.split("/"))
        if rel in same_new:
            print("ok  %s: already there, identical" % rel)
            continue
        d = os.path.dirname(full)
        if d and not os.path.isdir(d):
            os.makedirs(d)
        open(full, "wb").write(content.encode("utf-8"))
        print("ok  %s: new" % rel)
    for name in POST_CALLS:
        for line in globals()[name](HERE):
            print(line)
    print(DONE % (len(staged), len(NEW_FILES)))


if __name__ == "__main__":
    main()
